package com.networkmonitorpro.ui; import android.content.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;import androidx.fragment.app.*;import androidx.lifecycle.*;import com.networkmonitorpro.R;import com.networkmonitorpro.ui.viewmodel.MainViewModel;import java.io.*; public class SettingsFragment extends Fragment{ public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.fragment_settings,c,false);} public void onViewCreated(View v,Bundle b){MainViewModel m=new ViewModelProvider(requireActivity()).get(MainViewModel.class); Spinner sp=v.findViewById(R.id.themeSpinner); sp.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,new String[]{"System","Dark","Light","Dynamic"})); v.findViewById(R.id.clearHistory).setOnClickListener(x->{m.notifications.clear();m.downloads.clear();Toast.makeText(requireContext(),"History cleared",Toast.LENGTH_SHORT).show();}); v.findViewById(R.id.exportLogs).setOnClickListener(x->{try{File f=m.analytics.exportCsv(requireContext()); Uri u=FileProvider.getUriForFile(requireContext(),requireContext().getPackageName()+".fileprovider",f); startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/csv").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Export logs"));}catch(Exception e){Toast.makeText(requireContext(),e.getMessage(),Toast.LENGTH_LONG).show();}});} }
